import pandas as pd


def _is_null(v):
    try:
        return pd.isna(v)
    except Exception:
        return v is None


def _attrs_equal(a_cat, a_pb, b_cat, b_pb):
    # Compare tracked attributes with NULL semantics:
    # NULL vs NULL -> not a change; NULL vs non-NULL -> change; else normal compare.
    def eq(a, b):
        a_null = _is_null(a)
        b_null = _is_null(b)
        if a_null and b_null:
            return True
        if a_null != b_null:
            return False
        return a == b

    return eq(a_cat, b_cat) and eq(a_pb, b_pb)


def run(inputs: dict) -> dict:
    dim = inputs["DIM_PRODUCT"].copy()
    stg = inputs["STG_PRODUCT"].copy()

    # Build working list of row dicts preserving original columns/order
    cols = ["product_id", "category", "price_band", "eff_start_date",
            "eff_end_date", "is_current"]

    rows = []
    for _, r in dim.iterrows():
        rows.append({
            "product_id": r["product_id"],
            "category": r["category"],
            "price_band": r["price_band"],
            "eff_start_date": r["eff_start_date"],
            "eff_end_date": r["eff_end_date"],
            "is_current": r["is_current"],
        })

    # Track current row (by index into rows) per product_id
    current_idx = {}
    for i, r in enumerate(rows):
        if r["is_current"] == 1 or r["is_current"] == "1":
            current_idx[r["product_id"]] = i

    # Sort staged records by product_id, update_date ascending (stable sort,
    # no dedup)
    stg_sorted = stg.sort_values(
        by=["product_id", "update_date"],
        kind="mergesort"
    )

    for _, s in stg_sorted.iterrows():
        pid = s["product_id"]
        s_cat = s["category"]
        s_pb = s["price_band"]
        s_date = s["update_date"]

        idx = current_idx.get(pid)

        if idx is None:
            # No current row exists -> insert new current version
            new_row = {
                "product_id": pid,
                "category": s_cat,
                "price_band": s_pb,
                "eff_start_date": s_date,
                "eff_end_date": None,
                "is_current": 1,
            }
            rows.append(new_row)
            current_idx[pid] = len(rows) - 1
        else:
            c = rows[idx]
            if not _attrs_equal(c["category"], c["price_band"], s_cat, s_pb):
                # Expire current row
                c["eff_end_date"] = s_date
                c["is_current"] = 0
                # Insert new current version
                new_row = {
                    "product_id": pid,
                    "category": s_cat,
                    "price_band": s_pb,
                    "eff_start_date": s_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
                rows.append(new_row)
                current_idx[pid] = len(rows) - 1
            # else no-op

    out = pd.DataFrame(rows, columns=cols)

    # Align dtypes with input DIM_PRODUCT where possible
    for col in ["product_id", "is_current"]:
        if col in dim.columns:
            try:
                out[col] = out[col].astype(dim[col].dtype)
            except Exception:
                pass

    for col in ["category", "price_band"]:
        if col in dim.columns:
            try:
                out[col] = out[col].astype(dim[col].dtype)
            except Exception:
                pass

    return {"dim_product_out": out}
